import memfs, { Volume } from 'memfs'
import fs from 'fs'
import {
    createConsoleLogger,
    NowConfig,
    type FileSystem,
    GUID,
    zipDirectory,
    path,
    type Telemetry,
} from '@servicenow/sdk-build-core'
import { Orchestrator, Project } from '../../src'
import { MockConnector } from './mock-connector'
import * as os from 'os'

function createTelemetry(): Telemetry {
    return {
        sendEvent: jest.fn(),
        error: jest.fn(),
        startTimerEvent: jest.fn().mockReturnValue({
            end: jest.fn().mockReturnValue({ name: 'transform', data: {} }),
        }),
    } as unknown as Telemetry
}

let telemetry: Telemetry

describe('Orchestrator.transform Test Suite', () => {
    beforeEach(() => {
        jest.clearAllMocks()
        telemetry = createTelemetry()
    })

    const logger = createConsoleLogger()

    test('transform default with download metadata', async () => {
        const vol = new memfs.Volume()
        const fs = memfs.createFsFromVolume(vol)

        const project = new Project({
            fileSystem: fs as FileSystem,
            logger,
            rootDir: '/',
            config: NowConfig.parse({ scope: 'x_test', scopeId: GUID() }, logger),
            telemetryClient: telemetry,
        })

        const orchestrator = new Orchestrator(
            project,
            new MockConnector({
                download: async () => {
                    const body = await packMetadata(['businessrule.xml', 'sys_ui_form.xml'])
                    return new Response(body)
                },
            })
        )
        expect(project.getFiles()).toHaveLength(3)

        const result = await orchestrator.transform({})

        expect(telemetry.startTimerEvent).toHaveBeenCalledWith('transform')
        expect(telemetry.sendEvent).toHaveBeenCalled()
        expect(telemetry.error).not.toHaveBeenCalled()

        //Temp files should have been deleted after download
        const volFiles = Object.keys(vol.toJSON())
        expect(
            volFiles.some((v) => v.startsWith(os.tmpdir()) && (v.endsWith('.xml') || v.endsWith('.zip')))
        ).toBeFalsy()

        const files = project.getFiles()
        expect(files.some((f) => f.getPath().endsWith('businessrule.now.ts'))).toBeTruthy()
        expect(
            files.some((f) => f.getPath().endsWith('sys_script_d110d85a58a64040bdeadac72e9a2a6e.server.js'))
        ).toBeTruthy()
        expect(files.some((f) => f.getPath().endsWith('sys_ui_form.now.ts'))).toBeTruthy()
        expect(result.changedFiles).toHaveLength(3)
    })

    test('transform with directory argument', async () => {
        const paths = '/from-dir'
        const vol = copyMetadata(['businessrule.xml', 'sys_ui_form.xml'], paths, new Volume())
        const fs = memfs.createFsFromVolume(vol)

        const project = new Project({
            fileSystem: fs as FileSystem,
            logger,
            rootDir: '/',
            config: NowConfig.parse({ scope: 'x_test', scopeId: GUID() }, logger),
            telemetryClient: telemetry,
        })

        const orchestrator = new Orchestrator(project, new MockConnector({}))

        const transformResult = await orchestrator.transform({
            paths,
        })

        expect(telemetry.startTimerEvent).toHaveBeenCalledWith('transform')
        expect(telemetry.sendEvent).toHaveBeenCalled()
        expect(telemetry.error).not.toHaveBeenCalled()

        const files = project.getFiles()
        expect(files.some((f) => f.getPath().endsWith('businessrule.now.ts'))).toBeTruthy()
        expect(
            files.some((f) => f.getPath().endsWith('sys_script_d110d85a58a64040bdeadac72e9a2a6e.server.js'))
        ).toBeTruthy()
        expect(files.some((f) => f.getPath().endsWith('sys_ui_form.now.ts'))).toBeTruthy()
        expect(transformResult.changedFiles).toHaveLength(3)
    })

    test('transform with multiple files', async () => {
        const paths = '/from-dir'
        const vol = copyMetadata(['businessrule.xml', 'sys_ui_form.xml'], paths, new Volume())
        const fs = memfs.createFsFromVolume(vol)

        const project = new Project({
            fileSystem: fs as FileSystem,
            logger,
            rootDir: '/',
            config: NowConfig.parse({ scope: 'x_test', scopeId: GUID() }, logger),
            telemetryClient: telemetry,
        })

        const orchestrator = new Orchestrator(project, new MockConnector({}))

        const transformResult = await orchestrator.transform({
            paths: [path.join(paths, 'businessrule.xml'), path.join(paths, 'sys_ui_form.xml')],
        })

        expect(telemetry.startTimerEvent).toHaveBeenCalledWith('transform')
        expect(telemetry.sendEvent).toHaveBeenCalled()
        expect(telemetry.error).not.toHaveBeenCalled()
        const files = project.getFiles()
        expect(files.some((f) => f.getPath().endsWith('businessrule.now.ts'))).toBeTruthy()
        expect(
            files.some((f) => f.getPath().endsWith('sys_script_d110d85a58a64040bdeadac72e9a2a6e.server.js'))
        ).toBeTruthy()
        expect(files.some((f) => f.getPath().endsWith('sys_ui_form.now.ts'))).toBeTruthy()

        expect(files.find((f) => f.getPath().endsWith('businessrule.xml'))).toBeFalsy()
        expect(files.find((f) => f.getPath().endsWith('sys_ui_form.xml'))).toBeFalsy()

        expect(transformResult.changedFiles).toHaveLength(3)
        expect(transformResult.handledPaths).toHaveLength(2)
    })

    test('transform multiple files from metadata directory deletes sources', async () => {
        const paths = '/metadata'
        const vol = copyMetadata(['businessrule.xml', 'sys_ui_form.xml'], paths, new Volume())
        const fs = memfs.createFsFromVolume(vol)

        const project = new Project({
            fileSystem: fs as FileSystem,
            logger,
            rootDir: '/',
            config: NowConfig.parse({ scope: 'x_test', scopeId: GUID() }, logger),
            telemetryClient: telemetry,
        })

        const orchestrator = new Orchestrator(project, new MockConnector({}))

        const files1 = project.getFiles()
        expect(files1.some((f) => f.getPath().endsWith('businessrule.xml'))).toBeTruthy()
        expect(files1.some((f) => f.getPath().endsWith('sys_ui_form.xml'))).toBeTruthy()

        const transformResult = await orchestrator.transform({
            paths: [path.join(paths, 'businessrule.xml'), path.join(paths, 'sys_ui_form.xml')],
        })

        expect(telemetry.startTimerEvent).toHaveBeenCalledWith('transform')
        expect(telemetry.sendEvent).toHaveBeenCalled()
        expect(telemetry.error).not.toHaveBeenCalled()
        const files = project.getFiles()
        expect(files.some((f) => f.getPath().endsWith('businessrule.now.ts'))).toBeTruthy()
        expect(
            files.some((f) => f.getPath().endsWith('sys_script_d110d85a58a64040bdeadac72e9a2a6e.server.js'))
        ).toBeTruthy()
        expect(files.some((f) => f.getPath().endsWith('sys_ui_form.now.ts'))).toBeTruthy()

        expect(files.find((f) => f.getPath().endsWith('businessrule.xml'))).toBeFalsy()
        expect(files.find((f) => f.getPath().endsWith('sys_ui_form.xml'))).toBeFalsy()

        expect(transformResult.changedFiles).toHaveLength(3)
        expect(transformResult.handledPaths).toHaveLength(2)
    })

    test('transform files from non-meta directory does not delete sources', async () => {
        const paths = '/from-dir'
        const vol = copyMetadata(['businessrule.xml', 'sys_ui_form.xml'], paths, new Volume())
        const fs = memfs.createFsFromVolume(vol)

        const project = new Project({
            fileSystem: fs as FileSystem,
            logger,
            rootDir: '/',
            config: NowConfig.parse({ scope: 'x_test', scopeId: GUID() }, logger),
            telemetryClient: telemetry,
        })

        const orchestrator = new Orchestrator(project, new MockConnector({}))

        const transformResult = await orchestrator.transform({
            paths: [path.join(paths, 'businessrule.xml'), path.join(paths, 'sys_ui_form.xml')],
        })

        expect(telemetry.startTimerEvent).toHaveBeenCalledWith('transform')
        expect(telemetry.sendEvent).toHaveBeenCalled()
        expect(telemetry.error).not.toHaveBeenCalled()
        const files = project.getFiles()
        expect(files.some((f) => f.getPath().endsWith('businessrule.now.ts'))).toBeTruthy()
        expect(
            files.some((f) => f.getPath().endsWith('sys_script_d110d85a58a64040bdeadac72e9a2a6e.server.js'))
        ).toBeTruthy()
        expect(files.some((f) => f.getPath().endsWith('sys_ui_form.now.ts'))).toBeTruthy()

        expect(files.find((f) => f.getPath().endsWith('businessrule.xml'))).toBeFalsy()
        expect(files.find((f) => f.getPath().endsWith('sys_ui_form.xml'))).toBeFalsy()

        expect(fs.existsSync(path.join('/from-dir', 'businessrule.xml'))).toBeTruthy()
        expect(fs.existsSync(path.join('/from-dir', 'sys_ui_form.xml'))).toBeTruthy()

        expect(transformResult.changedFiles).toHaveLength(3)
        expect(transformResult.handledPaths).toHaveLength(2)
    })

    test('transform composite file from meta directory and delete sources', async () => {
        const paths = '/metadata'
        const vol = copyMetadata(['composite.xml', 'businessrule.xml'], paths, new Volume())
        const fs = memfs.createFsFromVolume(vol)

        const project = new Project({
            fileSystem: fs as FileSystem,
            logger,
            rootDir: '/',
            config: NowConfig.parse({ scope: 'x_test', scopeId: GUID() }, logger),
            telemetryClient: telemetry,
        })

        const orchestrator = new Orchestrator(project, new MockConnector({}))

        const transformResult = await orchestrator.transform({
            paths: [path.join(paths, 'composite.xml')],
        })

        expect(telemetry.startTimerEvent).toHaveBeenCalledWith('transform')
        expect(telemetry.sendEvent).toHaveBeenCalled()
        expect(telemetry.error).not.toHaveBeenCalled()
        const files = project.getFiles()
        expect(files.some((f) => f.getPath().endsWith('composite.now.ts'))).toBeTruthy()
        expect(
            files.some((f) => f.getPath().endsWith('sys_script_d110d85a58a64040bdeadac72e9a2a6d.server.js'))
        ).toBeTruthy()
        expect(
            files.some((f) => f.getPath().endsWith('sys_script_d110d85a58a64040bdeadac72e9a7777.server.js'))
        ).toBeTruthy()
        expect(files.some((f) => f.getPath().endsWith('businessrule.now.ts'))).toBeFalsy()

        const transformedContent = fs
            .readFileSync(
                path.join(
                    project.getFluentDir(),
                    'generated',
                    'server-development',
                    'business-rule',
                    'composite.now.ts'
                )
            )
            .toString('utf-8')
        expect(transformedContent).toMatch(`Now.ID['d110d85a58a64040bdeadac72e9a2a6d']`)
        expect(transformedContent).toMatch(`Now.ID['d110d85a58a64040bdeadac72e9a7777']`)

        expect(transformResult.changedFiles).toHaveLength(3)
        expect(transformResult.handledPaths).toHaveLength(1)
    })
})

describe('metadata folder transform behavior', () => {
    beforeEach(() => {
        jest.clearAllMocks()
        telemetry = createTelemetry()
    })
    const logger = createConsoleLogger()

    test('transform updates xml metadata as xml', async () => {
        const paths = '/metadata'
        const vol1 = copyMetadata(['composite.xml', 'businessrule.xml'], paths, new Volume())
        const vol2 = copyMetadata(['composite.xml', 'businessrule.xml'], '/from-dir', vol1)
        const fs = memfs.createFsFromVolume(vol2)

        const project = new Project({
            fileSystem: fs as FileSystem,
            logger,
            rootDir: '/',
            config: NowConfig.parse({ scope: 'x_test', scopeId: GUID() }, logger),
            telemetryClient: telemetry,
        })

        const orchestrator = new Orchestrator(project, new MockConnector({}))

        const transformResult = await orchestrator.transform({
            paths: ['from-dir/composite.xml', 'from-dir/businessrule.xml'],
        })

        expect(telemetry.startTimerEvent).toHaveBeenCalledWith('transform')
        expect(telemetry.sendEvent).toHaveBeenCalled()
        expect(telemetry.error).not.toHaveBeenCalled()

        expect(transformResult.changedFiles).toHaveLength(0)
        expect(transformResult.handledPaths).toHaveLength(0)
        const files = project.getFiles()
        expect(files.some((f) => f.getPath().endsWith('composite.now.ts'))).toBeFalsy()
        expect(files.some((f) => f.getPath().endsWith('businessrule.now.ts'))).toBeFalsy()

        expect(files.some((f) => f.getPath().endsWith('/metadata/composite.xml'))).toBeTruthy()
        expect(files.some((f) => f.getPath().endsWith('/metadata/businessrule.xml'))).toBeTruthy()
    })

    test('transform updates metadata xml content', async () => {
        const paths = '/metadata'
        const vol1 = copyMetadata(['businessrule.xml'], paths, new Volume())
        const vol2 = copyMetadataToFile(['businessrule-update.xml'], '/from-dir/businessrule.xml', vol1)
        const fs = memfs.createFsFromVolume(vol2)

        const project = new Project({
            fileSystem: fs as FileSystem,
            logger,
            rootDir: '/',
            config: NowConfig.parse({ scope: 'x_test', scopeId: GUID() }, logger),
            telemetryClient: telemetry,
        })

        const orchestrator = new Orchestrator(project, new MockConnector({}))

        const transformResult = await orchestrator.transform({
            paths: ['from-dir/businessrule.xml'],
        })

        expect(telemetry.startTimerEvent).toHaveBeenCalledWith('transform')
        expect(telemetry.sendEvent).toHaveBeenCalled()
        expect(telemetry.error).not.toHaveBeenCalled()

        expect(transformResult.changedFiles).toHaveLength(0)
        expect(transformResult.handledPaths).toHaveLength(0)
        const files = project.getFiles()
        expect(files.some((f) => f.getPath().endsWith('businessrule.now.ts'))).toBeFalsy()
        expect(files.some((f) => f.getPath().endsWith('/metadata/businessrule.xml'))).toBeTruthy()

        const resultContent = fs.readFileSync(`/metadata/businessrule.xml`).toString('utf-8')
        const expectedContent = fs.readFileSync(`/from-dir/businessrule.xml`).toString('utf-8')

        expect(resultContent).toMatch(expectedContent)
    })

    test('metadata copy ignores directory change and uses original location', async () => {
        const paths = '/metadata/update'
        const vol1 = copyMetadata(['businessrule.xml'], paths, new Volume())
        const vol2 = copyMetadata(['businessrule.xml'], '/from-dir/author_elective_update', vol1)
        const fs = memfs.createFsFromVolume(vol2)

        const project = new Project({
            fileSystem: fs as FileSystem,
            logger,
            rootDir: '/',
            config: NowConfig.parse({ scope: 'x_test', scopeId: GUID() }, logger),
            telemetryClient: telemetry,
        })

        const orchestrator = new Orchestrator(project, new MockConnector({}))

        const transformResult = await orchestrator.transform({
            paths: ['from-dir/author_elective_update/businessrule.xml'],
        })

        expect(telemetry.startTimerEvent).toHaveBeenCalledWith('transform')
        expect(telemetry.sendEvent).toHaveBeenCalled()
        expect(telemetry.error).not.toHaveBeenCalled()

        expect(transformResult.changedFiles).toHaveLength(0)
        expect(transformResult.handledPaths).toHaveLength(0)
        const files = project.getFiles()
        expect(files.some((f) => f.getPath().endsWith('businessrule.now.ts'))).toBeFalsy()
        expect(files.some((f) => f.getPath().endsWith('/metadata/businessrule.xml'))).toBeFalsy()

        const resultContent = fs.readFileSync(`/metadata/update/businessrule.xml`).toString('utf-8')
        const expectedContent = fs.readFileSync(`/from-dir/author_elective_update/businessrule.xml`).toString('utf-8')

        expect(resultContent).toMatch(expectedContent)
    })

    test('metadata copy handles sub directory', async () => {
        const paths = '/metadata/if'
        const vol1 = copyMetadata(['businessrule.xml'], paths, new Volume())
        const vol2 = copyMetadata(['businessrule-update.xml'], '/from-dir/if', vol1)
        const fs = memfs.createFsFromVolume(vol2)

        const project = new Project({
            fileSystem: fs as FileSystem,
            logger,
            rootDir: '/',
            config: NowConfig.parse({ scope: 'x_test', scopeId: GUID() }, logger),
            telemetryClient: telemetry,
        })

        const orchestrator = new Orchestrator(project, new MockConnector({}))

        const transformResult = await orchestrator.transform({
            paths: ['from-dir'],
        })

        expect(telemetry.startTimerEvent).toHaveBeenCalledWith('transform')
        expect(telemetry.sendEvent).toHaveBeenCalled()
        expect(telemetry.error).not.toHaveBeenCalled()

        expect(transformResult.changedFiles).toHaveLength(0)
        expect(transformResult.handledPaths).toHaveLength(0)
        const files = project.getFiles()
        expect(files.some((f) => f.getPath().endsWith('businessrule.now.ts'))).toBeFalsy()
        expect(files.some((f) => f.getPath().endsWith('/metadata/businessrule.xml'))).toBeFalsy()
        expect(files.some((f) => f.getPath().endsWith('/metadata/if/businessrule-update.xml'))).toBeTruthy()

        const resultContent = fs.readFileSync(`/metadata/if/businessrule-update.xml`).toString('utf-8')
        const expectedContent = fs.readFileSync(`/from-dir/if/businessrule-update.xml`).toString('utf-8')

        expect(resultContent).toMatch(expectedContent)
    })

    test('transforms a single record provided via sysIds', async () => {
        const sysId = 'd110d85a58a64040bdeadac72e9a2a6e'
        const scopeId = '11111111111111111111111111111111'

        const connector = new MockConnector({
            unloadRecords: jest.fn(async () => [
                {
                    content: fs.readFileSync(path.join(__dirname, 'metadata', 'businessrule.xml'), 'utf-8'),
                    sysId,
                    table: 'sys_script',
                    tableName: 'sys_script',
                    name: 'Test BR',
                },
            ]),
        })

        const fsMem = memfs.createFsFromVolume(new memfs.Volume()) as FileSystem
        const project = new Project({
            fileSystem: fsMem,
            rootDir: '/',
            config: { scope: 'x_test', scopeId },
        })

        const orchestrator = new Orchestrator(project, connector)

        // Execute transform using DownloadMetadataOptions like payload
        const result = await orchestrator.transform({ method: 'sys-id', sysIds: [sysId] })

        // Verify file was transformed
        expect(result.changedFiles).toHaveLength(2)
        const transformedFile = result.changedFiles[0]
        expect(transformedFile.getName()).toContain(sysId)
        // Ensure file content includes the ID reference
        expect(transformedFile.getContent()).toContain(sysId)

        // Confirm connector was invoked properly
        expect(connector.unloadRecords).toHaveBeenCalledWith([sysId], scopeId)
    })

    test('transforms multiple records provided via sysIds', async () => {
        const scopeId = '11111111111111111111111111111111'
        const br = 'd110d85a58a64040bdeadac72e9a2a6e'
        const form = 'bd72ef90c3824dedbeaa7c8c08cca3b5'

        const connector = new MockConnector({
            unloadRecords: jest.fn(async () => [
                {
                    content: fs.readFileSync(path.join(__dirname, 'metadata', 'businessrule.xml'), 'utf-8'),
                    sysId: br,
                    table: 'sys_script',
                    tableName: 'sys_script',
                    name: 'Test BR',
                },
                {
                    content: fs.readFileSync(path.join(__dirname, 'metadata', 'sys_ui_form.xml'), 'utf-8'),
                    sysId: form,
                    table: 'sys_ui_form',
                    tableName: 'sys_ui_form',
                    name: 'Test Form',
                },
            ]),
        })

        const fsMem = memfs.createFsFromVolume(new memfs.Volume()) as FileSystem
        const project = new Project({
            fileSystem: fsMem,
            rootDir: '/',
            config: { scope: 'x_test', scopeId },
        })

        const orchestrator = new Orchestrator(project, connector)

        // Execute transform using DownloadMetadataOptions like payload
        const result = await orchestrator.transform({ method: 'sys-id', sysIds: [br, form] })

        expect(result.changedFiles).toHaveLength(3)
        // Verify file 1 was transformed
        const transformedBr = result.changedFiles[0]
        expect(transformedBr.getName()).toContain(br)
        // Ensure file content includes the ID reference
        expect(transformedBr.getContent()).toContain(br)

        // Verify file 2 was transformed
        const transformedForm = result.changedFiles[2]
        expect(transformedForm.getName()).toContain(form)
        // Ensure file content includes the ID reference
        expect(transformedForm.getContent()).toContain(form)

        // Confirm connector was invoked properly
        expect(connector.unloadRecords).toHaveBeenCalledWith([br, form], scopeId)
    })

    test('transforms record provided via sysIds even if some are not present', async () => {
        const scopeId = '11111111111111111111111111111111'
        const br = 'd110d85a58a64040bdeadac72e9a2a6e'
        const form = 'bd72ef90c3824dedbeaa7c8c08cca3b5'

        const connector = new MockConnector({
            unloadRecords: jest.fn(async () => [
                {
                    content: fs.readFileSync(path.join(__dirname, 'metadata', 'businessrule.xml'), 'utf-8'),
                    sysId: br,
                    table: 'sys_script',
                    tableName: 'sys_script',
                    name: 'Test BR',
                },
            ]),
        })

        const fsMem = memfs.createFsFromVolume(new memfs.Volume()) as FileSystem
        const project = new Project({
            fileSystem: fsMem,
            rootDir: '/',
            config: { scope: 'x_test', scopeId },
        })

        const orchestrator = new Orchestrator(project, connector)

        // Execute transform using DownloadMetadataOptions like payload
        const result = await orchestrator.transform({ method: 'sys-id', sysIds: [br, form] })

        expect(result.changedFiles).toHaveLength(2)
        // Verify file 1 was transformed
        const transformedBr = result.changedFiles[0]
        expect(transformedBr.getName()).toContain(br)
        // Ensure file content includes the ID reference
        expect(transformedBr.getContent()).toContain(br)

        // Confirm connector was invoked properly
        expect(connector.unloadRecords).toHaveBeenCalledWith([br, form], scopeId)
    })
})

function copyMetadataToFile(files: string[], copyToPath: string, vol: memfs.Volume) {
    const json = files.reduce<Record<string, string>>((acc, file) => {
        acc[path.join(copyToPath)] = fs.readFileSync(path.join(__dirname, 'metadata', file), 'utf-8')
        return acc
    }, {})

    vol.fromJSON(json)
    return vol
}

function copyMetadata(files: string[], copyToPath: string, vol: memfs.Volume) {
    const json = files.reduce<Record<string, string>>((acc, file) => {
        acc[path.join(copyToPath, file)] = fs.readFileSync(path.join(__dirname, 'metadata', file), 'utf-8')
        return acc
    }, {})

    vol.fromJSON(json)
    return vol
}

async function packMetadata(files: string[]) {
    const vol = copyMetadata(files, '', new Volume())
    const memFileSystem = memfs.createFsFromVolume(vol) as FileSystem

    const zip = await zipDirectory(memFileSystem, '/', '/metadata.zip')
    return vol.readFileSync(zip)
}
